import {heading,cta,price} from './shared.js';
export const services=()=>`<section class="section container" id="servicos">${heading('PRESENÇA DIGITAL, DO SEU JEITO','O que podemos criar<br>para o seu negócio?')}<div class="service-grid">${[['01','▱','Página de Vendas','Páginas estratégicas criadas para apresentar sua oferta, gerar interesse e transformar visitantes em contatos.'],['02','⌘','Site Profissional','Um site moderno para apresentar sua empresa, serviços, diferenciais e facilitar o contato com seus clientes.'],['03','⌖','Presença no Google','Ajude sua empresa a ser encontrada por pessoas que já estão procurando pelo seu serviço.']].map(([n,i,t,p])=>`<article class="service-card reveal"><div class="card-top"><span class="icon">${i}</span><span>${n}</span></div><h3>${t}</h3><p>${p}</p><a href="#contato">Vamos criar o seu <span>↗</span></a></article>`).join('')}</div></section>`;
export const offer=()=>`<section class="container offer-section reveal"><div><span class="eyebrow">UMA NOVA PRESENÇA. UM NOVO COMEÇO.</span><h2>Pequeno investimento.<br><em>Grande primeira impressão.</em></h2><p>Uma página moderna, responsiva e personalizada para apresentar o seu negócio de forma profissional.</p><ul class="offer-list">${['Design profissional','Adaptado para celular','Botão direto para WhatsApp','Seções personalizadas','Identidade visual do seu negócio','Estrutura preparada para divulgação'].map(x=>`<li>✓ <span>${x}</span></li>`).join('')}</ul></div><div class="price-card"><span class="pill">✦ OFERTA ESPECIAL</span><p>Seu site profissional por</p>${price()}<span class="price-caption">Uma página. Todas as possibilidades.</span>${cta('QUERO COMEÇAR MEU PROJETO')}<small>Vamos conversar sobre o que seu negócio precisa.</small></div></section>`;
